interface LanguageContextType {
  currentLanguage: SupportedLanguage;
  setLanguage: (lang: SupportedLanguage) => void;
  t: (key: string, fallback?: string) => string;
  speechCode: string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentLanguage, setCurrentLanguageState] = useState<SupportedLanguage>(() => {
    const savedLang = localStorage.getItem('GREENFLEET_LANGUAGE');
    return (savedLang as SupportedLanguage) || 'English';
  });

  const setLanguage = (lang: SupportedLanguage) => {
    setCurrentLanguageState(lang);
    localStorage.setItem('GREENFLEET_LANGUAGE', lang);
  };

  const t = (key: string, fallback?: string): string => {
    const dict = TRANSLATIONS[currentLanguage] || TRANSLATIONS.English;
    if (dict[key]) return dict[key];
    if (TRANSLATIONS.English[key]) return TRANSLATIONS.English[key];
    return fallback || key;
  };

  const speechCode = LANG_SPEECH_CODES[currentLanguage] || 'en-IN';

  return (
    <LanguageContext.Provider value={{ currentLanguage, setLanguage, t, speechCode }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};
